$(function(){new Lazyload,$(".btn-down").click(function(){$("html,body").animate({scrollTop:$(".loyalty-section").offset().top},600)}),$(".btn-up").click(function(){$("html,body").animate({scrollTop:$(".top-section").offset().top},600)}),$(".hamburguer-icon").click(function(a){a.preventDefault(),$(".mobile-submenu").toggleClass("mobile-submenu-anim"),$(".close-mobile-menu").toggleClass("close-mobile-menu-anim")}),$(".close-mobile-menu").click(function(a){a.preventDefault(),$(".mobile-submenu").toggleClass("mobile-submenu-anim"),$(".close-mobile-menu").toggleClass("close-mobile-menu-anim")}),$(".features-btn").click(function(a){a.preventDefault(),$("html,body").animate({scrollTop:$(".loyalty-section").offset().top},600)}),$(".benefits-btn").click(function(a){a.preventDefault(),$("html,body").animate({scrollTop:$(".blue-section").offset().top},600)}),$(".tools-list a").click(function(a){a.preventDefault();var b="."+$(this).data("section");$("html,body").animate({scrollTop:$(b).offset().top-70},1200)})});